(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0017.js"] = [{"id":"glyph-seal-5962","script":"seal","character":"奢","reading":"shē","description":"shē：(1)用钱没有节制，过分享受～侈。～靡。穷～极欲。\n(2)过分的～盼。～求。～望。\n(3)夸张～言。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-奢"},{"id":"glyph-seal-5965","script":"seal","character":"奥","reading":"ào；yù","description":"ào：(1)含义深，不易理解深～。～妙。～秘。～旨。\n(2)室内的西南角，泛指房屋及其他深处隐蔽的地方堂～。经堂入～。\n(3)姓。\nyù：(1)浊。\n(2)古同燠”，暧。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-奥"},{"id":"glyph-seal-596d","script":"seal","character":"奭","reading":"shì","description":"shì：(1)盛大的样子。\n(2)红色。\n(3)恼怒。\n(4)消散的样子。\n(5)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-奭"},{"id":"glyph-seal-5973","script":"seal","character":"女","reading":"nǚ；rǔ","description":"nǚ：(1)女性，与男”相对。古代以未婚的为女”，已婚的为妇”。现通称妇女”～人。～士。～流（含轻蔑意）。少（shào）～。\n(2)以女儿作为人的妻（旧读nǜ）。\n(3)星名，二十八宿之一。亦称婺女”、须女”。\n儿；子；父；母；男；\nrǔ：古同汝”，你。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-女"},{"id":"glyph-seal-5974","script":"seal","character":"奴","reading":"nú","description":"nú：(1)阶级社会中受压迫、剥削、役使的没有人身自由的人农～。～隶。～婢（男女奴仆）。～颜婢膝。～性。\n(2)像对待奴隶那样地～役。～使。\n(3)使人甘受奴役地～化。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-奴"},{"id":"glyph-seal-5978","script":"seal","character":"奸","reading":"jiān","description":"jiān：(1)阴险，虚伪，狡诈～人。～狡。～刁。～佞。～雄。～智（为非作歹的心计）。藏（cáng）～。\n(2)不忠于国家或自己一方的人～细。内～。\n(3)男女发生不正当的性行为～淫。强～（亦指统治者把自己的意志强加于人民，如～～民意”）。通～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-奸"},{"id":"glyph-seal-597d","script":"seal","character":"好","reading":"hǎo；hào","description":"hǎo：优良，美好；友好；容易。hào：喜爱，常常倾向于做某事，如爱好、好学。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-5981","script":"seal","character":"妁","reading":"shuò","description":"shuò：媒人媒～（撮合男女婚事的人）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妁"},{"id":"glyph-seal-5982","script":"seal","character":"如","reading":"rú","description":"rú：(1)依照顺从～愿。～意。～法炮制。\n(2)像，相似，同什么一样～此。～是。～同。～故。～初。游人～织。\n(3)比得上，及百闻不～一见。自叹弗～。\n(4)到，往～厕。\n(5)假若，假设～果。～若。假～。\n(6)奈，怎么～何。不能正其身，～正人何？\n(7)与，和公～大夫入”。\n(8)或者方六七十，～五六十”。\n(9)用在形容词后，表示动作或事物的状态突～其来。\n(10)表示举例例～。\n(11)应当若知不能，则～无出”。\n(12)姓。\n〔～月〕农历二月的别称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-如"},{"id":"glyph-seal-5983","script":"seal","character":"妃","reading":"fēi；pèi","description":"fēi：(1)帝王的妻，位次于皇后；亦指太子、王、侯的妻～子。～嫔。\n(2)古代对神女的尊称天～。宓～。\n(3)古同绯”，粉红色。\npèi：古同配”，婚配。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妃"},{"id":"glyph-seal-5984","script":"seal","character":"妄","reading":"wàng","description":"wàng：(1)胡乱，荒诞不合理轻举～动。胆大～为。～自尊大。～图。狂～。～想。\n(2)非分的，不实的姑～听之。～自菲薄。～作主张。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妄"},{"id":"glyph-seal-5986","script":"seal","character":"妆","reading":"zhuāng","description":"梦啼妆泪红阑干。\n假装。同装”\n⒈修饰，打扮～饰。梳～。\n⒉特指妇女用的装饰物当户理红～。\n⒊演员身上的装饰卸～。\n⒋女子出嫁时的陪送物品嫁～。送～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妆"},{"id":"glyph-seal-5987","script":"seal","character":"妇","reading":"fù","description":"泛指妇女,常指成年女子\n⒈女性的通称～孺。～科。三八国际～女节。\n⒉妻，已婚的女子，跟\"夫\"相对～人。夫～平等。\n⒊儿媳媳～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妇"},{"id":"glyph-seal-598a","script":"seal","character":"妊","reading":"rèn","description":"rèn：怀孕～娠。～妇。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妊"},{"id":"glyph-seal-598d","script":"seal","character":"妍","reading":"yán","description":"yán：(1)美丽～媸（美好和丑恶）。百花争～。\n(2)巧～捷。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妍"},{"id":"glyph-seal-5992","script":"seal","character":"妒","reading":"dù","description":"dù：因为别人好而忌恨嫉～。～恨。～羡。嫉贤～能。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妒"},{"id":"glyph-seal-5993","script":"seal","character":"妓","reading":"jì","description":"jì：(1)以卖淫为生的女子～女。娼～。～院。\n(2)古代称歌女，表演歌舞的女子歌～。舞～。歌舞～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妓"},{"id":"glyph-seal-5997","script":"seal","character":"妗","reading":"jìn","description":"jìn：(1)舅母。\n(2)妻兄、妻弟的妻子大～子。小～子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妗"},{"id":"glyph-seal-5999","script":"seal","character":"妙","reading":"miào","description":"miào：(1)美，好～语。～不可言。美～。～境。～处（chù）（a.好的地点；b.美妙的方面）。绝～。～趣横生。\n(2)奇巧，神奇巧～。～计。～用。奥～。～笔生花。灵丹～药。\n(3)青春年少～年。～龄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妙"},{"id":"glyph-seal-59a3","script":"seal","character":"妣","reading":"bǐ","description":"bǐ：原指母亲，后称已经死去的母亲先～。如丧考～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妣"},{"id":"glyph-seal-59a5","script":"seal","character":"妥","reading":"tuǒ","description":"tuǒ：(1)适当，合适稳～。不～。～当（dàng）。～贴（恰当，十分合适。亦作妥帖”）。～善。～协（让步，放弃争执）。\n(2)安稳，停当（多用在动词后）已经商量～了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妥"},{"id":"glyph-seal-59a8","script":"seal","character":"妨","reading":"fáng","description":"fáng：(1)阻碍，伤害～碍。～害。无～。不～∥～。\n(2)迷信的人指某人或某物对人不利～主。～家。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妨"},{"id":"glyph-seal-59a9","script":"seal","character":"妩","reading":"wǔ","description":"娇美\n美女","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妩"},{"id":"glyph-seal-59aa","script":"seal","character":"妪","reading":"yù","description":"以体相温\n养育;抚育\n东海莫贤\n妪yǔ 1.以体相温。 2.指养育。 3.和悦貌。参见\"妪然\"﹑\"妪妪\"等。 4.恭顺貌。参见\"妪\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妪"},{"id":"glyph-seal-59ab","script":"seal","character":"妫","reading":"guī","description":"即妫水\n古州名。辖境相当于今河北省赤城、怀来等地\n妫guì 1.健狡。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妫"},{"id":"glyph-seal-59af","script":"seal","character":"妯","reading":"zhóu","description":"zhóu：〔～娌〕兄和弟的妻子合称或互称，如她们三个是～～”（娌”读轻声）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妯"},{"id":"glyph-seal-59b2","script":"seal","character":"妲","reading":"dá","description":"dá：〔～己〕古人名，中国商代纣王的宠妃。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妲"},{"id":"glyph-seal-59b9","script":"seal","character":"妹","reading":"mèi","description":"mèi：(1)称同父母（或只同父、只同母）而比自己年纪小的女子～～。兄～。弟～（a.弟弟和妹妹的合称；b.俗称弟妇）。～夫。\n(2)对比自己年纪小的同辈女性的称呼表～。师～。世～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妹"},{"id":"glyph-seal-59bb","script":"seal","character":"妻","reading":"qī；qì","description":"qī：男子的配偶～子。～室（指妻子）。～小（妻子和儿女）。～离子散。\n夫；\nqì：以女嫁人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妻"},{"id":"glyph-seal-59be","script":"seal","character":"妾","reading":"qiè","description":"qiè：(1)旧时男人娶的小老婆。\n(2)谦辞，旧时女人自称～身。贱～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-妾"},{"id":"glyph-seal-59ca","script":"seal","character":"姊","reading":"zǐ","description":"zǐ：姐姐～妹（a.姐姐和妹妹；b.同辈女朋友亲热的称呼）。～夫。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姊"},{"id":"glyph-seal-59cb","script":"seal","character":"始","reading":"shǐ","description":"shǐ：(1)起头，最初，与终”相对开～。～终。～祖。～创。周而复～。\n(2)才，刚才方～。～悟（才觉悟到）。春蚕到死丝方尽，蜡炬成灰泪～干。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-始"},{"id":"glyph-seal-59d0","script":"seal","character":"姐","reading":"jiě","description":"jiě：(1)称同父母（或只同父、只同母）而比自己年纪大的女子～～。～夫。～弟。\n(2)对比自己年纪大的同辈女性的称呼表～。师～。大～（a.对一般年轻妇女的称呼；b.对排行最大的姐姐的称呼）。\n(3)对未婚女子的通称小～（旧时称上层社会未婚女子，现多用于交际场合）。小大～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姐"},{"id":"glyph-seal-59d1","script":"seal","character":"姑","reading":"gū","description":"gū：(1)称父亲的姐妹～～。～父。～表（一家的父亲和另一家的母亲是兄妹或姐弟的亲戚关系，如～～兄弟”）。\n(2)丈夫的姊妹小～子。～嫂。\n(3)旧时妻称夫的母亲翁～。舅～。\n(4)少女，亦作妇女的通称～娘（a.未婚少女，娘”读轻声；b.姑母）。道～。尼～。\n(5)暂且，苟且～且。～息。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姑"},{"id":"glyph-seal-59d3","script":"seal","character":"姓","reading":"xìng","description":"xìng：(1)表明家族的字～氏。～名。贵～（询问对方姓氏的敬辞）。\n(2)平民万～。老百～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姓"},{"id":"glyph-seal-59d4","script":"seal","character":"委","reading":"wěi；wēi","description":"wěi：(1)任，派，把事交给人办～托。～派。～任。～员。～以重任。\n(2)抛弃，舍弃～弃。～之于地。\n(3)推托，卸推～。～罪。\n(4)曲折，弯转～曲。～婉。～屈。\n(5)积聚～积。\n(6)末、尾原～。穷源意～（追究事物本原及其发展）。\n(7)确实～实。\n(8)无精打采，不振作～顿。～靡。\nwēi：〔～蛇（yí）〕a.敷衍，应付；b.同逶迤”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-委"},{"id":"glyph-seal-59d7","script":"seal","character":"姗","reading":"shān；shàn","description":"shān：〔～～〕形容走路缓缓从容的样子，如～～来迟”。\nshàn：古同讪”，讥讽。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姗"},{"id":"glyph-seal-59d8","script":"seal","character":"姘","reading":"pīn","description":"pīn：非夫妻而同居的不正当的男女关系～居。～头（头”读轻声）。～夫。～妇。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姘"},{"id":"glyph-seal-59da","script":"seal","character":"姚","reading":"yáo","description":"yáo：(1)美好的样子～冶（妖艳）。\n(2)姓。\n(3)古同遥”，远。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姚"},{"id":"glyph-seal-59dc","script":"seal","character":"姜","reading":"jiāng","description":"jiāng：(1)多年生草本植物，地下茎黄色，味辣，可供调味用，亦可入药生～。～汤。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姜"},{"id":"glyph-seal-59dd","script":"seal","character":"姝","reading":"shū","description":"shū：(1)美丽，美好～丽。～好。\n(2)美女丽～。\n(3)柔顺～～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姝"},{"id":"glyph-seal-59e3","script":"seal","character":"姣","reading":"jiāo；xiáo","description":"jiāo：美好～人（美人）。～美。～好。～冶（艳丽）。～艳。\nxiáo：淫乱弃位而～，不可谓贞”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姣"},{"id":"glyph-seal-59e8","script":"seal","character":"姨","reading":"yí","description":"yí：(1)称母亲的姊妹～母。～妈。～父。\n(2)妻的姊妹大～子。小～子。\n(3)妾～太太。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姨"},{"id":"glyph-seal-59ec","script":"seal","character":"姬","reading":"jī","description":"jī：(1)古代对妇女的美称。\n(2)中国汉代宫中的女官。\n(3)旧时称妾～人。～妾。～侍。\n(4)旧时称以歌舞为业的女子歌～。\n(5)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姬"},{"id":"glyph-seal-59f9","script":"seal","character":"姹","reading":"chà","description":"chà：(1)美丽～女。～紫嫣红（花色娇艳）。\n(2)夸耀子虚过～乌有先生。”","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姹"},{"id":"glyph-seal-59fb","script":"seal","character":"姻","reading":"yīn","description":"yīn：(1)男女嫁娶婚～。～缘。\n(2)由婚姻关系而结成的亲属～亲。联～。\n(3)较间接的亲戚关系～故。～旧。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姻"},{"id":"glyph-seal-59ff","script":"seal","character":"姿","reading":"zī","description":"zī：(1)面貌，容貌～容。丰～。～色。天～。\n(2)形态，样子～态。～势。舞～。风～。英～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姿"},{"id":"glyph-seal-5a01","script":"seal","character":"威","reading":"wēi","description":"wēi：(1)表现出来使人敬畏的气魄～力。～风。权～。\n(2)凭借力量或势力～胁。～慑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-威"},{"id":"glyph-seal-5a03","script":"seal","character":"娃","reading":"wá","description":"wá：(1)小孩子～子。胖～～。\n(2)旧称美女娇～。\n(3)某些幼小的动物猪～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娃"},{"id":"glyph-seal-5a04","script":"seal","character":"娄","reading":"lóu","description":"物体中空的\n收敛\n二十八宿之一,西方白虎七宿的第二宿。有白羊座α、β、γ星三颗\n母猪\n通塿”。小土丘\n假借为屡”\n娄lǘ 1.牵，曳。\n娄lǚ 1.拴系。 2.卷曲。参见\"娄络\"。\n娄lǒu 1.见\"部娄\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娄"},{"id":"glyph-seal-5a06","script":"seal","character":"娆","reading":"ráo","description":"柔弱\n妍媚\n嬈娆\n戏弄\n娆yǎo 1.柔弱貌。参见\"娆娆\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娆"},{"id":"glyph-seal-5a07","script":"seal","character":"娇","reading":"jiāo","description":"⒈美好可爱万紫千红分外～。\n⒉柔嫩，怕苦怕累～嫩。～气。\n⒊宠爱～惯。～生惯养。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娇"},{"id":"glyph-seal-5a08","script":"seal","character":"娈","reading":"luán","description":"美好，常用于形容容貌。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-5a09","script":"seal","character":"娉","reading":"pīng","description":"pīng：〔～婷〕形容女子姿态美好。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娉"},{"id":"glyph-seal-5a11","script":"seal","character":"娑","reading":"suō","description":"suō：〔婆～〕见婆”。\n〔～～〕轻扬、松散的样子，如修初服之～～兮，长余佩之参参（shēn shēn）”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娑"},{"id":"glyph-seal-5a13","script":"seal","character":"娓","reading":"wěi","description":"wěi：顺从。\n〔～～〕形容谈话不倦或说话具有吸引力，如～～而谈”、～～动听”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娓"},{"id":"glyph-seal-5a18","script":"seal","character":"娘","reading":"niáng","description":"niáng：(1)母亲～亲。～家。爹～。\n(2)对年轻女子的称呼～子。姑～。娇～。新～。\n(3)称长一辈或年长的已婚妇女大～。婶～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娘"},{"id":"glyph-seal-5a1f","script":"seal","character":"娟","reading":"juān","description":"juān：秀丽，美好～丽。～秀。～～（秀美的样子）。～媚。婵～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娟"},{"id":"glyph-seal-5a20","script":"seal","character":"娠","reading":"shēn","description":"shēn：胎儿在母体中微动，泛指怀孕妊～（怀孕）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娠"},{"id":"glyph-seal-5a23","script":"seal","character":"娣","reading":"dì","description":"dì：(1)古代称丈夫的弟妇～姒（妯娌）。\n(2)古代姐姐称妹妹。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娣"},{"id":"glyph-seal-5a25","script":"seal","character":"娥","reading":"é","description":"é：(1)女子姿容美好～眉。～～（美好的样子）。\n(2)美女娇～。宫～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娥"},{"id":"glyph-seal-5a31","script":"seal","character":"娱","reading":"yú","description":"yú：快乐或使人快乐～乐（lè）。～老（欢度晚年）。～亲（使父母快乐）。～悦。自～。～情陶性。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娱"},{"id":"glyph-seal-5a32","script":"seal","character":"娲","reading":"wā","description":"古神女名\n娲guā 1.庖娲，古代神话传说中女娲氏的别称。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娲"},{"id":"glyph-seal-5a34","script":"seal","character":"娴","reading":"xián","description":"⒈文雅，雅静～雅。～丽。\n⒉熟练～熟。～于辞令。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娴"},{"id":"glyph-seal-5a36","script":"seal","character":"娶","reading":"qǔ","description":"qǔ：把女子接过来成亲～亲。～妻。迎～。嫁～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娶"},{"id":"glyph-seal-5a40","script":"seal","character":"婀","reading":"ē","description":"ē：〔～娜（nuó）〕柔美的样子，如～～多姿”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-婀"},{"id":"glyph-seal-5a49","script":"seal","character":"婉","reading":"wǎn","description":"wǎn：(1)和顺，（说话）曲折含蓄～顺。～转（zhuǎn）（亦作宛转”）。委～。～辞。\n(2)美好，柔美～丽。～约。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-婉"},{"id":"glyph-seal-5a55","script":"seal","character":"婕","reading":"jié","description":"jié：〔～妤〕中国汉代宫中女官名。自魏晋至明代多沿置。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-婕"},{"id":"glyph-seal-5a5a","script":"seal","character":"婚","reading":"hūn","description":"hūn：男女结为夫妇结～。新～。已～。～姻。～约。～礼。～变。～娶。～外恋。离～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-婚"},{"id":"glyph-seal-5a62","script":"seal","character":"婢","reading":"bì","description":"bì：被役使的女子奴～。～女。奴颜～膝。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-婢"},{"id":"glyph-seal-5a67","script":"seal","character":"婧","reading":"jìng","description":"jìng：(1)纤弱苗条的样子舒妙～之纤腰兮”。\n(2)（女子）有才品。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-婧"},{"id":"glyph-seal-5a6a","script":"seal","character":"婪","reading":"lán","description":"lán：贪爱财物贪～。～酣。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-婪"},{"id":"glyph-seal-5a74","script":"seal","character":"婴","reading":"yīng","description":"初生的女孩\n亦泛指初生儿\n系到颈上;戴\n辟之,是犹使处女婴宝珠、\n⒈初生的小孩～儿。女～。\n⒊碰，触犯国富民强，敌国不敢～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-婴"},{"id":"glyph-seal-5a75","script":"seal","character":"婵","reading":"chán","description":"婵娟\n绮窗罗幕锁婵娟\n婵媛\n【婵娟】\n②指月亮。又作婵媛。\n【婵媛】\n①见【婵娟】。\n②牵连；相连。\n婵shàn 1.见\"婉婵\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-婵"},{"id":"glyph-seal-5a7a","script":"seal","character":"婺","reading":"wù","description":"wù：〔～水〕水名，在中国江西省。\n〔～绿〕产于中国江西省婺源县的茶叶，是绿茶中的珍品。\n〔～女〕古星宿名，即女宿”。\n〔～剧〕中国浙江省地方戏曲剧种之一。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-婺"},{"id":"glyph-seal-5a7f","script":"seal","character":"婿","reading":"xù","description":"xù：(1)丈夫夫～。\n(2)女儿、妹妹及其他晚辈的丈夫女～。妹～。侄～。甥～。贤～。翁～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-婿"},{"id":"glyph-seal-5a92","script":"seal","character":"媒","reading":"méi","description":"méi：(1)撮合男女婚事的人～人。～妁（旧指婚姻介绍人）。～婆。\n(2)使双方发生关系的人或事物～介。～体。触～。传～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-媒"},{"id":"glyph-seal-5a9a","script":"seal","character":"媚","reading":"mèi","description":"mèi：(1)谄，逢迎～外。～世（迎合世俗）。～眼。～惑。～态。谄～。献～。奴颜～骨。\n(2)美好，可爱～景。明～。秀～。妩～。娇～。\n(3)喜爱我既～君姿，君亦悦我颜。”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-媚"},{"id":"glyph-seal-5a9b","script":"seal","character":"媛","reading":"yuán；yuàn","description":"yuàn：美女～女。才～。名～。\nyuán：〔婵～〕见婵”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-媛"},{"id":"glyph-seal-5aaa","script":"seal","character":"媪","reading":"ǎo；yùn；wò","description":"ǎo：古代对妇女的通称。\nyùn：古女子人名用字。\nwò：〔～妠〕小肥。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-媪"},{"id":"glyph-seal-5ab2","script":"seal","character":"媲","reading":"pì","description":"pì：并，比，匹敌～美。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-媲"},{"id":"glyph-seal-5abe","script":"seal","character":"媾","reading":"gòu","description":"gòu：(1)连合，结合婚～。\n(2)交合～合。交～。\n(3)交好～和。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-媾"},{"id":"glyph-seal-5ac1","script":"seal","character":"嫁","reading":"jià","description":"jià：(1)女子结婚出～。～娶。再～。～奁。～妆。\n(2)把祸害、怨恨推到别人身上～怨。～祸于人。～非（委过于人）。转～。\n〔～接〕把不同品种的两种植物接在一起，让它变种，达到提早结果、增加抗性、提高品种质量等目的。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嫁"},{"id":"glyph-seal-5ac2","script":"seal","character":"嫂","reading":"sǎo","description":"sǎo：(1)哥哥的妻子～～。～子。兄～。\n(2)泛称年岁不大的已婚妇女大～。～夫人（对朋友妻子的尊称）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嫂"},{"id":"glyph-seal-5ac9","script":"seal","character":"嫉","reading":"jí；jī","description":"jī：(1)因别人比自己好而怨恨～妒。～恨。～羡。\n(2)憎恨～恶如仇。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嫉"},{"id":"glyph-seal-5acc","script":"seal","character":"嫌","reading":"xián","description":"xián：(1)可疑之点～疑。避～。涉～。\n(2)厌恶，不满意～恶（wù）。～弃。讨人～。\n(3)怨尽释前～。～隙（由猜疑而形成的仇怨）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嫌"},{"id":"glyph-seal-5ad4","script":"seal","character":"嫔","reading":"pín","description":"跟从\n古代妇女的通称。亦对妇人的美称\n帝王诸侯的姬妾\n⒈〈古〉皇宫里的女官。\n⒉女子出嫁。\n⒊〈古〉妻死后的称呼。\n⒋［嫔然］形容众多。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嫔"},{"id":"glyph-seal-5ad6","script":"seal","character":"嫖","reading":"piáo；piāo","description":"piáo：玩弄娼妓的堕落行为～妓。～宿。～客。吃喝～赌。\npiāo：〔～姚〕勇健轻捷的样子，如以～～校尉再从大将军”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嫖"},{"id":"glyph-seal-5ada","script":"seal","character":"嫚","reading":"màn；mān","description":"màn：轻慢、侮慢。mān：部分方言中称女孩。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-5ae0","script":"seal","character":"嫠","reading":"lí","description":"lí：寡妇～妇。～节（指封建社会寡妇的节操，夫死不再改嫁）。～不恤纬（喻忧国忘家）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嫠"},{"id":"glyph-seal-5ae1","script":"seal","character":"嫡","reading":"dí","description":"dí：(1)封建宗法制度中指正妻～庶。\n(2)正妻所生的～子。～出（正妻所生，区别于庶出”）。\n(3)亲的，血统最近的，封建宗法制度下家庭的正支～亲。～嗣。\n(4)系统最近的，正统的～系。～派。～传。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嫡"},{"id":"glyph-seal-5ae3","script":"seal","character":"嫣","reading":"yān","description":"yān：容貌美好，多指笑容～然一笑。姹紫～红（形容百花艳丽）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嫣"},{"id":"glyph-seal-5ae9","script":"seal","character":"嫩","reading":"nèn","description":"nèn：(1)初生而柔弱娇～。～芽。\n(2)（颜色）淡；浅～绿。～黄。\n(3)幼稚；不老练稚～。～手。\n(4)轻；微～寒清晓。”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嫩"},{"id":"glyph-seal-5af1","script":"seal","character":"嫱","reading":"qiáng","description":"古代宫廷中女官的称谓。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-5b16","script":"seal","character":"嬖","reading":"bì","description":"bì：宠幸～爱。便～。～幸。～人。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嬖"},{"id":"glyph-seal-5b17","script":"seal","character":"嬗","reading":"shàn","description":"shàn：(1)更替，变迁～变（演变，蜕变）。～替。\n(2)古同禅”，传位，禅让。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嬗"},{"id":"glyph-seal-5b34","script":"seal","character":"嬴","reading":"yíng","description":"yíng：(1)姓。\n(2)古同赢”，获胜。\n(3)古同赢”，满，有余。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嬴"},{"id":"glyph-seal-5b50","script":"seal","character":"子","reading":"zǐ","description":"zǐ：(1)古代指儿女，现专指儿子～女。～孙。～嗣。～弟（后辈人，年轻人）。\n(2)植物的果实、种子菜～。瓜～儿。～实。\n(3)动物的卵鱼～。蚕～。\n(4)幼小的，小的～鸡。～畜。～城。\n(5)小而硬的颗粒状的东西～弹（dàn）。棋～儿。\n(6)与母”相对～金（利息）。～母扣。～音（辅音）。\n(7)对人的称呼男～。妻～。士～（读书人）。舟～（船夫）。才～。\n(8)古代对人的尊称；称老师或称有道德、有学问的人孔～。先秦诸～。\n(9)地支的第一位，属鼠～丑寅卯（喻有条不紊的层次或事物的条理）。\n(10)用于计时～时（夜十一点至一点）。～夜（深夜）。\n(11)封建制度五等爵位的第四等～爵。\n(12)附加在名词、动词、形容词后，具有名词性（读轻声）旗～。乱～。胖～。\n(13)个别量词后缀（读轻声）敲了两下～门。\n(14)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-子"},{"id":"glyph-seal-5b51","script":"seal","character":"孑","reading":"jié","description":"jié：(1)单独，孤单～然一身。茕茕～立。～遗生物（活化石）。\n(2)古同戟”，古代兵器名。\n〔～孓〕蚊的幼虫。通称跟头虫”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孑"},{"id":"glyph-seal-5b53","script":"seal","character":"孓","reading":"jué","description":"jué：〔孑～〕见孑”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孓"},{"id":"glyph-seal-5b54","script":"seal","character":"孔","reading":"kǒng","description":"kǒng：(1)小洞，窟窿～穴。～眼。～洞。～方兄（指钱，因旧时的铜钱有方形的孔，恢谐含鄙意）。\n(2)很～急。～武有力。\n(3)量词，用于窑洞一～土窑。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孔"},{"id":"glyph-seal-5b55","script":"seal","character":"孕","reading":"yùn","description":"yùn：胎，怀胎怀～。～妇。～育（怀胎生育，喻既存事物中酝酿着新事物）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孕"},{"id":"glyph-seal-5b57","script":"seal","character":"字","reading":"zì","description":"zì：(1)用来记录语言的符号文～『～。～符。～母。～典。～句。～里行（háng）间。～斟句酌。\n(2)文字的不同形式，书法的派别草～。篆～。颜～。柳～。欧～。赵～。\n(3)书法的作品～画。～幅。\n(4)字的音～正腔圆。\n(5)人的别名，亦称表～”，现多称号”；商店的名称，亦称～号”。\n(6)合同，契约～据。\n(7)旧时称女子出嫁待～闺中。\n(8)生子，乳，爱～乳（生育）。～孕（怀孕）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-字"},{"id":"glyph-seal-5b58","script":"seal","character":"存","reading":"cún","description":"cún：(1)东西在那里，人活着～在。～亡。生～。\n(2)保留，留下保～。留～。～照。～疑。去伪～真。\n(3)寄放寄～。\n(4)停聚～水。\n(5)怀有，怀着～心。不～任何奢望。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-存"},{"id":"glyph-seal-5b59","script":"seal","character":"孙","reading":"sūn","description":"跟孙子同辈的同性或异性亲属\n⒈儿子的子女～子。～女。\n⒉孙子以后各代曾～。玄～。子～后代。\n⒊跟孙子同辈的亲属外～子。侄～女。\n⒋植物再生或孳生的稻～。～竹。\n⒌〈古〉通\"逊\"。逃。\n孙xùn 1.谦顺;恭顺。 2.逃遁;流亡。 3.退出﹑让出帝位或某职位。 4.差，比不上。\n孙xún 1.见\"孙子\"﹑\"孙孟\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孙"},{"id":"glyph-seal-5b5a","script":"seal","character":"孚","reading":"fú","description":"fú：(1)信用。\n(2)为人所信服深～众望。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孚"},{"id":"glyph-seal-5b5b","script":"seal","character":"孛","reading":"bó；bèi","description":"bèi：(1)草木茂盛的样子。\n(2)古书上指光芒强盛的彗星。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孛"},{"id":"glyph-seal-5b5c","script":"seal","character":"孜","reading":"zī","description":"zī：〔～～〕勤谨，不懈怠，如～～不倦”、～～以求”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孜"},{"id":"glyph-seal-5b5d","script":"seal","character":"孝","reading":"xiào","description":"xiào：(1)对父母尽心奉养并顺从～敬。～廉（ａ．中国汉代盐官吏的科目之一，孝”指孝子；廉”指廉洁的人；ｂ．中国明、清两代对举人的称呼）。～道。～子贤孙。\n(2)居丧的事守～。吊～。\n(3)丧服戴～。～衣。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孝"},{"id":"glyph-seal-5b5f","script":"seal","character":"孟","reading":"mèng","description":"mèng：(1)兄弟姊妹排行最大的～兄。～女（长女）。～孙。\n(2)农历四季中月份在开头的（其它两个月依次为仲、季）～春（农历正月）。\n(3)猛然不及思考，冒冒失失～行。～浪。\n(4)勉力～晋（勉力求进）。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孟"},{"id":"glyph-seal-5b63","script":"seal","character":"季","reading":"jì","description":"jì：(1)兄弟排行次序最小的～弟（小弟）。～父（小叔叔）。\n(2)末了～世。～春（春季末一月）。明～（明代末年）。～军（体育运动竞赛的第三名）。\n(3)一年的四分之一一年分春夏秋冬四～。～度。～风。\n(4)一段时间～节。～候。～相（xiàng）（某个地区在某个季节的自然景象）。雨～。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-季"},{"id":"glyph-seal-5b64","script":"seal","character":"孤","reading":"gū","description":"gū：(1)幼年死去父亲或父母双亡～儿。遗～。托～。～寡鳏独（孤儿，寡妇，无妻或丧妻的人，年老无子女的人）。\n(2)单独～单。～独。～立。～僻。～傲。～茕（单独无依然）。～介。～身。～危。～芳自赏。～苦伶仃。～掌难鸣。～云野鹤（喻闲逸逍遥的人）。\n(3)古代帝王的自称～家。～王。\n(4)古同辜”，辜负。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孤"},{"id":"glyph-seal-5b66","script":"seal","character":"学","reading":"xué","description":"⒈指学习～工。～农。～医。～哲学。～而不厌。～习科学知识。\n⒉模仿边看边～。照字帖～写字。鹦鹉～舌。\n⒊指学问。\n①反映客观事物的系统知识这是一门新兴的～问。\n②知识求～。博～多才。\n③学和问勤～多问。\n⒋指学识，学术上的知识和修养她的～识渊博。\n⒌指学校，集体培养人才的地方小～。中～。大～。\n⒍指学科，分门别类的有系统的知识医～。化～。生物～。经济～。\n①在学校学习的人。\n②向前辈或向能者学习的人。\n③求学者谦称自己。\n①〈古〉官名翰林～士。\n②旧称学者文人～士。\n③学位名在硕士之下。\n学xiào 1.教导。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-学"},{"id":"glyph-seal-5b69","script":"seal","character":"孩","reading":"hái","description":"hái：儿童，引申为子女男～儿。～童。～提（指幼儿时期）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孩"},{"id":"glyph-seal-5b6a","script":"seal","character":"孪","reading":"luán","description":"双生,俗称双胞胎","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孪"},{"id":"glyph-seal-5b71","script":"seal","character":"孱","reading":"chán；càn","description":"chán：(1)软弱，弱小～王（软弱无能的君王）。～弱。～～。\n(2)卑微～琐（卑贱无能）。～微（地位低微）。\n(3)窘迫。\ncàn：义同（一）①，只用于孱头”（方言，软弱无能的人）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孱"},{"id":"glyph-seal-5b73","script":"seal","character":"孳","reading":"zī","description":"zī：滋生，繁殖～生。～乳（动物生子繁殖，或指事物生生不已）。\n〔～～〕同孜孜”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孳"},{"id":"glyph-seal-5b7a","script":"seal","character":"孺","reading":"rú","description":"rú：小孩子，幼儿～子。～慕（幼童对父母的爱慕，泛指深挚的敬爱或仰慕）。～子牛。妇～皆知。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孺"},{"id":"glyph-seal-5b7d","script":"seal","character":"孽","reading":"niè","description":"niè：(1)恶因，恶事，邪恶～臣（奸佞之臣）。～种（zhǒng）。～根。～海。～障（ａ．长辈骂后辈为不肖子弟的话；ｂ．佛教指妨碍修行的种种罪恶。均亦称业障”）。作～（做伤天害理的事）。罪～（罪恶）。造～。\n(2)奴隶社会、封建社会多妻制下指妾及其子女～妾。～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孽"},{"id":"glyph-seal-5b81","script":"seal","character":"宁","reading":"níng","description":"⒈安定，平安～静。康～。既安且～。\n⒉南京市的简称。\n⒈情愿～可。～愿。～缺毋滥。～死不屈。\n⒊文言副词。岂，难道王侯将相～有种乎？\n宁zhù 1.古代宫室门屏之间。 2.同\"贮\"。贮藏;积聚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宁"},{"id":"glyph-seal-5b83","script":"seal","character":"它","reading":"tā","description":"tā：代词，称人以外的事物～们。其～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-它"},{"id":"glyph-seal-5b85","script":"seal","character":"宅","reading":"zhái","description":"zhái：(1)住所，房子（多指较大的）住～。内～（指住宅内女眷的住处）。～门。～邸。～第。\n(2)葬地，墓穴～兆（坟墓的四界）。\n(3)居住～心仁厚（居心仁义厚道）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宅"},{"id":"glyph-seal-5b87","script":"seal","character":"宇","reading":"yǔ","description":"yǔ：(1)屋檐，泛指房屋～下（屋檐之下，喻在他人庇护之下）。屋～。庙～。～宙（ａ．屋檐和栋梁；ｂ．空间与时间；ｃ．天地）。\n(2)国土，疆土故～。\n(3)整个空间世界～内（指天下）。玉～。～航。\n(4)风度，仪表眉～（指人的样子，仪表）。器～轩昂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宇"},{"id":"glyph-seal-5b88","script":"seal","character":"守","reading":"shǒu","description":"shǒu：(1)保持，卫护～成（在事业上保持前人的成就）。～御。～身（爱护自身，保持自己的品节）。～节。～恒。～望相助。墨～成规。\n(2)看管看～。～护。\n(3)在一个地方不动～株待兔。留～。\n(4)遵照遵～。～法。～时。\n(5)维持原状，不想改变保～。因循～旧。\n(6)呆在一起厮～。\n(7)节操操～。\n(8)靠近，依傍～着水的地方，可多种稻子。\n(9)古代官名太～。～祧（中国周代掌管祭祀宗庙的官）。～刺（太守，刺史）。～令（指太守、刺史、县令等地方官）。\n(10)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-守"},{"id":"glyph-seal-5b89","script":"seal","character":"安","reading":"ān","description":"ān：(1)平静，稳定～定。～心。～宁。～稳。～闲。～身立命。～邦定国。\n(2)使平静，使安定（多指心情）～民。～慰。～抚。\n(3)对生活工作等感觉满足合适心～。～之若素（遇到不顺利情况或反常现象像平常一样对待，毫不在意）。\n(4)没有危险，不受威协平～。转危为～。\n(5)装设～置。～家立业。\n(6)存着，怀着（某种念头，多指不好的）他～的什么心？\n(7)疑问词，哪里～能如此？\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-安"},{"id":"glyph-seal-5b8b","script":"seal","character":"宋","reading":"sòng","description":"sòng：(1)中国周代诸侯国名，在今河南省商丘市一带。\n(2)中国朝代名南～。～代。～词。\n(3)响度单位，一宋约相当于人耳刚能听到的声音响度的一千倍，等于1000毫宋。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宋"},{"id":"glyph-seal-5b8c","script":"seal","character":"完","reading":"wán","description":"wán：(1)全～备。～全。～整。～善。～好。～璧归赵。覆巢无～卵。\n(2)尽，无用～了。煤烧～了。\n(3)做成，了结～毕。～成。～结。\n(4)交纳～粮。～税。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-完"},{"id":"glyph-seal-5b8f","script":"seal","character":"宏","reading":"hóng","description":"hóng：(1)广大，博大～大。～伟。～图。～愿。～论。～丽。～亮。～观。宽～。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宏"},{"id":"glyph-seal-5b93","script":"seal","character":"宓","reading":"mì；fú","description":"mì：(1)安静。\n(2)姓。\nfú：古同伏”，伏羲”亦作宓羲”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宓"},{"id":"glyph-seal-5b95","script":"seal","character":"宕","reading":"dàng","description":"dàng：(1)拖延，搁置～欠。～账（拖延不还的账）。延～。\n(2)放荡，不受拘束流～。～逸（飘逸，洒脱）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宕"},{"id":"glyph-seal-5b97","script":"seal","character":"宗","reading":"zōng","description":"zōng：(1)家族的上辈，民族的祖先祖～。～庙。～祠。\n(2)家族～法（封建社会以家族为中心，按制统远近区别亲疏的制度）。～族。～室（帝王的宗族）。～兄。\n(3)派别～派。禅～（佛教的一派）。\n(4)主要的目的和意图～旨。开～明义。\n(5)尊奉～仰。\n(6)为众人所师法的人物～师。\n(7)量词，指件或批一～心事。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宗"},{"id":"glyph-seal-5b98","script":"seal","character":"官","reading":"guān","description":"guān：(1)在政府担任职务的人～吏。～僚。～邸。～腔。～署。～厅。～爵。\n(2)属于国家的或公家的～办。～费。～方。～府。\n(3)生物体上有特定机能的部分感～。器～。五～。～能。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-官"},{"id":"glyph-seal-5b99","script":"seal","character":"宙","reading":"zhòu","description":"zhòu：古往今来所有的时间宇～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宙"},{"id":"glyph-seal-5b9a","script":"seal","character":"定","reading":"dìng","description":"dìng：(1)不动的，不变的～额。～价。～律。～论。～期。～型。～义。～都（dū）。～稿。～数（shù）（ａ．规定数额；ｂ．指天命；ｃ．规定的数额）。断～。规～。鉴～。\n(2)使不变动～案。～罪。决～。确～。\n(3)平安，平靖（多指局势）大局已～。\n(4)镇静，安稳（多指情绪）心神不～。\n(5)确凿，必然的必～。镇～。\n(6)预先约妥～计。～情。～货。～做。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-定"},{"id":"glyph-seal-5b9b","script":"seal","character":"宛","reading":"wǎn；yuān","description":"wǎn：(1)曲折委～。～妙（声音婉转动听）。～转（zhuǎn）（ａ．辗转；ｂ．同婉转”）。\n(2)仿佛～然。～如。～若（仿佛，好像）。\n(3)姓。\nyuān：〔大～〕古代西域国名，在中亚西亚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宛"},{"id":"glyph-seal-5b9c","script":"seal","character":"宜","reading":"yí","description":"yí：(1)适合，适当～人。～于∠～。权～。适～。相～。\n(2)应该，应当事不～迟。\n(3)当然，无怪～其无往而不利也。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宜"},{"id":"glyph-seal-5b9d","script":"seal","character":"宝","reading":"bǎo","description":"①珍贵的东西粮食是个～，谁都离不了。\n②珍贵的～刀。\n③旧时的一种赌具。\n④旧时用于称别人的家眷、铺子等的敬辞～眷、～号。\n【宝船】明代滞下西洋时使用的海船的名称。据有关资料，最大的船长158米，宽56米。\n【宝石】硬度较大，色泽美丽，受到大气和化学药品的作用不起变化，产量稀少而极为贵重的矿物，统称为宝石。如金刚石、刚玉、黄玉、硬玉、绿柱石等。\n【宝惜】珍惜。\n【宝座】\n①帝王或神佛的座位。\n②借指某一职位或荣誉冠军～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宝"},{"id":"glyph-seal-5b9e","script":"seal","character":"实","reading":"shí","description":"真实;诚实\n夫图画,\n⒈满，充满～心铅球。～足岁数。仓库充～。\n⒉种子，果子果～。\n⒊真，诚恳，不狡猾真～。诚～。老～。说～话。\n⒋客观存在的～事。～际。～力。～况。事～。\n⒌的确确～。\n⒍用于加强语气～难从命。\n⒎施，执行，推行～施。～行。\"\n①真，的确～在对。\n②不虚假，不马虎他干活很～在。\n③其实，实际他说懂了，～在是哄骗人。\n①客观的真实情况。也指实践联系～际。\n②具体的～际效果。\n①人们改造自然和改造社会的活动。\n②实行及履行自己的主张或诺言。\n①为了检验某种科学理论或假设而进行的观察和研究活动。\n②指实验的工作。\n实zhì 1.到达。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-实"},{"id":"glyph-seal-5ba0","script":"seal","character":"宠","reading":"chǒng","description":"宠爱\n【宠爱】过分喜爱；偏爱。\n【宠辱不惊】无论受宠或是受辱都无动于衷。形容把荣辱得失置之度外。\n【宠辱若惊】受宠受辱都感到不安。形容患得患失。\n【宠幸】旧时指帝王对后妃、臣下宠爱，后泛指地位高的人对地位低的人的宠爱。\n⒈偏爱，溺爱～爱。\n⒉荣耀～辱不惊。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宠"},{"id":"glyph-seal-5ba1","script":"seal","character":"审","reading":"shěn","description":"知道,知悉\n⒈周密，详细～慎。精～。用意详～。〈引〉细思，细查，推究，评定，弄明白～查。～核。～稿。～议。～定。～时度势。\n⒊知道，明白，也作\"谂\"～悉。当局者迷，旁观者～。\n⒋确实，果然～如其言。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-审"},{"id":"glyph-seal-5ba2","script":"seal","character":"客","reading":"kè","description":"kè：(1)外来的（人），与主”相对～人。宾～。会～。不速之～。～气。～卿。\n(2)外出或寄居，迁居外地的（人）旅～。～居。～籍。～死。\n(3)服务行业的服务对象顾～。乘～。～流量。\n(4)指奔走各地从事某种活动的人说～。政～。侠～。\n(5)在人类意识外独立存在的～观。～体。\n(6)量词，用于论份儿出售的食品、饮料一～冰淇淋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-客"},{"id":"glyph-seal-5ba3","script":"seal","character":"宣","reading":"xuān","description":"xuān：(1)公开说出，散布～讲。～传。～战。～称。～言。～叙调。心照不～。\n(2)疏导～泄。\n(3)古代帝王的大室。\n(4)皇帝命令或传达皇帝的命令～付。～召（皇帝召见）。～诏（传旨）。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宣"},{"id":"glyph-seal-5ba4","script":"seal","character":"室","reading":"shì","description":"shì：(1)屋子，房间，亦指家居～。教～。会客～。温～。引狼入～。\n(2)家，家族皇～。女有家，男有～。\n(3)机关团体内部的工作单位档案～。\n(4)古指妻子（亦指为子娶妻或以女嫁人）妻～。继～。\n(5)刀剑的鞘。\n(6)墓穴。\n(7)星名，二十八宿之一。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-室"},{"id":"glyph-seal-5ba5","script":"seal","character":"宥","reading":"yòu","description":"yòu：宽容，饶恕，原谅～罪。～恕。原～。宽～。尚希见～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宥"},{"id":"glyph-seal-5ba6","script":"seal","character":"宦","reading":"huàn","description":"huàn：(1)官，做官官～。仕～。～海。～游。\n(2)阉人，太监～官。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宦"},{"id":"glyph-seal-5baa","script":"seal","character":"宪","reading":"xiàn","description":"喜乐的样子\n法令\n宪法的略称\n⒈法令～章。布～。\n⒉效法，摹仿。\n⒊指宪法立～。\n定其它法律的根据。\n宪xiǎn 1.明显。参见\"宪宪\"。 2.犹皇。旧时对先人的美称。参见\"宪考\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宪"},{"id":"glyph-seal-5bab","script":"seal","character":"宫","reading":"gōng","description":"gōng：(1)房屋（封建时代专指帝王的住所）～室。～廷。～殿。～观（guàn）（ａ．供帝王游乐的离宫；ｂ．道教的庙宇）。～禁。～苑。～刑。\n(2)神话中神仙居住的房屋天～。龙～。蟾～。\n(3)庙宇的名称雍和～。\n(4)一些文化娱乐场所少年～。文化～。\n(5)天文上黄道分为十二宫，每一宫三十度。\n(6)中国古代五音之一，相当于简谱1”。\n(7)指子宫”（妇女生殖器官）。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宫"},{"id":"glyph-seal-5bb0","script":"seal","character":"宰","reading":"zǎi","description":"zǎi：(1)杀牲畜～杀。屠～。～牲节（亦称古尔邦节”、牺牲节”）。\n(2)借指商贩用狡诈的手段使顾客在经济上受到损害（有的地区称斩”）。\n(3)古代官名～相（xiàng）。～辅。太～。～官。\n(4)主管、主持主～。～制。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宰"},{"id":"glyph-seal-5bb3","script":"seal","character":"害","reading":"hài","description":"hài：(1)有损的，与益”相对～虫。～鸟。\n(2)引起灾难的人或事物，坏处～处。祸～。灾～。为民除～。\n(3)使受损伤～人。损～。伤～。危～。\n(4)发生疾病～眼。\n(5)心理上发生不安定情绪～羞。～怕。\n(6)杀死杀～。遇～。\n(7)妒忌上官大夫与之同列，争宠而心～其能”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-害"},{"id":"glyph-seal-5bb4","script":"seal","character":"宴","reading":"yàn","description":"yàn：(1)以酒饭款待宾客～客。～饮。～席。\n(2)聚会在一起吃酒饭～会。～集。\n(3)酒席设～。国～。盛（shéng）～。\n(4)乐（lè），安闲～娱。～嬉。～乐（yuè）。～居。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宴"},{"id":"glyph-seal-5bb5","script":"seal","character":"宵","reading":"xiāo","description":"xiāo：夜通～达旦。春～。～夜。～禁。～衣旰食（天不亮就起来，天黑了才吃饭，形容勤于政务）。～遁。元～。夜～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宵"},{"id":"glyph-seal-5bb6","script":"seal","character":"家","reading":"jiā","description":"jiā：(1)共同生活的眷属和他们所住的地方～庭。～眷。～长（zhǎng）。～园。～谱。～塾。～乡。～风。～训。～规。～喻户晓。如数～珍。\n(2)家庭所在的地方回～。老～。安～。\n(3)居住可以～焉”。\n(4)对人称自己的尊长、亲属～祖。～父。～翁。～母。～慈。\n(5)家里养的，不是野生的～畜。～禽。\n(6)经营某种行业的人家或有某种身份的人家酒～。农～。\n(7)掌握某种专门学识或有丰富实践经验及从事某种专门活动的人专～。行（háng）～。作～。科学～。\n(8)学术流派儒～。法～。道～。墨～。纵横～。诸子百～。\n(9)量词，用于计算家庭或企业一～人家。\n(10)姓。\n野；\nji：(1)词尾，指一类的人老人～。\n(2)用在男人的名字或排行后面，指他的妻水生～","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-家"},{"id":"glyph-seal-5bb8","script":"seal","character":"宸","reading":"chén","description":"chén：(1)屋宇，深邃的房屋。\n(2)北极星所在，后借指帝王所居，又引申为王位、帝王的代称～极。～居。～章。～札（帝王的书札）。～游。～翰（帝王的书迹）。～垣（京师）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宸"},{"id":"glyph-seal-5bb9","script":"seal","character":"容","reading":"róng","description":"róng：(1)包含，盛（chéng）～器。～量（liàng）。～积。～纳。无地自～。\n(2)对人度量大～忍。宽～。\n(3)让，允许～让。不～人说话。\n(4)相貌，仪表，景象，状态～止。～颜。～光。～貌。仪～。军～。市～。阵～。姿～。\n(5)或许，也许～或。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-容"},{"id":"glyph-seal-5bbd","script":"seal","character":"宽","reading":"kuān","description":"广阔;面积大。与狭”相对\n横的距离大\n度量宽宏;宽厚\n宽而栗\n⒈阔大，跟\"窄\"相对～阔。～敞。～广。～银幕。\n⒉松缓，放松～心。放～。〈引〉\n①脱去，解除请～了风衣。\n②伸延～限三天。\n③宽大～猛相济。处理从～。\n⒊富裕～裕。～绰。\n⒋度量大～宏大量。～大为怀。\n⒌物体横的距离～度。三尺～的布。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宽"},{"id":"glyph-seal-5bbe","script":"seal","character":"宾","reading":"bīn","description":"诸侯、诸伯、诸子、诸男之相为宾也。诸公之臣相为国客,是散文宾客通称,对称则宾尊而客卑,\n②客人贵～。\n③姓。\n【宾白】道白。古典戏曲用语。\n【宾词】一个命题的三个部分之一，表示思考对象的属性。如'竹子是植物'中的'植物'。又叫谓项。\n【宾服】服从；佩服。\n【宾格】屈折语中一种格的形式，表示该词是及物动词的宾语。如英语的him、me等。\n【宾客图】见【礼宾图】。\n【宾语补足语】补充说明宾语的成分。如'we call him james'中的'james'。\n【宾至如归】客人到这里如同回到自己家一样亲切。形容旅馆、饭店等招待客人很周到、热情。\n宾bìn 1.摈弃;排除;拒却。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宾"},{"id":"glyph-seal-5bbf","script":"seal","character":"宿","reading":"xiǔ；sù；xiù","description":"sù：(1)住，过夜，夜里睡觉住～。留～。露～。～舍（shè）。～营。\n(2)年老的，长久从事某种工作的～将（经验丰富的老将）。～儒。名～。\n(3)平素，素有的～愿。～志。～疾。～敌。～心。\n(4)隔夜的，隔年的～雨（昨夜的雨）。～根。～草。\n(5)姓。\nxiǔ：夜一～。两～。\nxiù：星座星～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宿"},{"id":"glyph-seal-5bc2","script":"seal","character":"寂","reading":"jì","description":"jì：静，没有声音～静。～寞。孤～。～～。～灭。～默。～寥（寂静空旷）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寂"},{"id":"glyph-seal-5bc4","script":"seal","character":"寄","reading":"jì","description":"jì：(1)托付～托。～存。～情。～怀。～意。\n(2)依靠，依附～居。～食。～生虫。\n(3)托人传送，特指由邮局传递～信。～钱。\n(4)认的亲属～父。～母。～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寄"},{"id":"glyph-seal-5bc5","script":"seal","character":"寅","reading":"yín","description":"yín：(1)地支的第三位，属虎～吃卯粮（喻入不敷出）。\n(2)用于计时～时（夜三点至五点）。\n(3)敬～钱（恭敬地送）。～畏（敬畏）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寅"},{"id":"glyph-seal-5bc6","script":"seal","character":"密","reading":"mì","description":"mì：(1)稠，空隙小，与稀”、疏”相对紧～。稠～。茂～。严～。～封。～布。～集。～匝匝。～锣紧鼓（喻正式活动前的积极而紧张的准备，亦作紧锣密鼓”）。\n(2)关系近，感情好～友。～亲。\n(3)不公开，不公开的事物秘～。保～。～谋。～电。～报。～使。～信。～诏。～旨。～探。\n(4)精致，细致精～。细～。致～。～实（细密结实）。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-密"},{"id":"glyph-seal-5bc7","script":"seal","character":"寇","reading":"kòu","description":"kòu：(1)盗匪，侵略者，亦指敌人盗～。贼～。\n(2)侵略者来侵犯～边。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寇"},{"id":"glyph-seal-5bcc","script":"seal","character":"富","reading":"fù","description":"fù：(1)财产、财物多～有。～足。～饶。～庶。～裕。～强。～豪。财～。～国强兵。\n(2)充裕，充足～余。～态。～丽堂皇。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-富"},{"id":"glyph-seal-5bd0","script":"seal","character":"寐","reading":"mèi","description":"mèi：睡，睡着（zháo）～语。假（jiǎ）～。梦～以求。夙兴（xīng）夜～（早起晚睡）。夜不能～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寐"},{"id":"glyph-seal-5bd2","script":"seal","character":"寒","reading":"hán","description":"hán：(1)冷，与暑”相对～冬。～色。～衣。～冽。～带。～战。～噤。～食（节名，在清明前一天。古人从这一天起不生火做饭，也有的地区把清明当作寒食”）。～喧。～来暑往。唇亡齿～。\n(2)害怕～心。\n(3)穷困，有时用作谦辞～门。～伧。～舍。～窗（喻艰苦的学习环境）。～酸。～士（旧指贫穷的读书人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寒"},{"id":"glyph-seal-5bd3","script":"seal","character":"寓","reading":"yù","description":"yù：(1)原指寄居，后泛指居住～公（古代指寄居他国的官僚贵族；后泛指失势寄居他乡的地主绅士等人）。～居。～所。～舍。～邸。\n(2)住的地方公～。客～。\n(3)寄托寄～。～目（过目）。～言（a.有所寄托的话；b.用来说明某个道理的小故事）。～意（语言文字中所寄托或暗含的意思）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寓"},{"id":"glyph-seal-5bdf","script":"seal","character":"察","reading":"chá","description":"chá：仔细看，调查研究～看。～核。观～。考～（a.实地观察调查，如科学～～”；b.细致深刻地观察，如科学研究要勤于～～和思考”）。～觉。～访。～勘。～探。明～秋毫（秋毫”指秋天鸟兽身上新长的细毛，喻为人精明，任何小问题都看得清楚）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-察"},{"id":"glyph-seal-5be1","script":"seal","character":"寡","reading":"guǎ","description":"guǎ：(1)少，缺少～薄。～恩。～陋。～趣。优柔～断。～不敌众。孤陋～闻。～廉鲜（xiǎn）耻（不廉洁，不知耻）。清心～欲。\n(2)淡而无味～味。清汤～水。\n(3)妇女死了丈夫～妇。～母。～居。守～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寡"},{"id":"glyph-seal-5be4","script":"seal","character":"寤","reading":"wù","description":"wù：(1)睡醒七日而～”。～寐以求。\n(2)古同悟”，理解，明白。\n(3)古同牾”，逆。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寤"},{"id":"glyph-seal-5bf0","script":"seal","character":"寰","reading":"huán","description":"huán：(1)广大的地域人～。瀛～（五洲四海）。～海。～球。～宇（亦作环宇”）。\n(2)古指距京都千里以内的地区，京畿～内诸侯，非有天子之命，不得出会诸侯”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寰"},{"id":"glyph-seal-5bf8","script":"seal","character":"寸","reading":"cùn","description":"cùn：(1)中国市制长度单位，一尺的十分之一尺～。\n(2)短小～土。～阴（日影移动一寸的时间）。～心。～步难行。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寸"},{"id":"glyph-seal-5bf9","script":"seal","character":"对","reading":"duì","description":"唐且对曰臣未尝闻也。”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-对"},{"id":"glyph-seal-5bfa","script":"seal","character":"寺","reading":"sì","description":"sì：(1)古代官署名太常～（古代掌管宗庙礼仪的官署）¤胪～（略同于现代的礼宾司）。\n(2)佛教出家人居住的地方佛～。～观（guàn）。\n(3)伊斯兰教徒礼拜、讲经的地方清真～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寺"},{"id":"glyph-seal-5bfb","script":"seal","character":"寻","reading":"xún","description":"精巧,寻仞皆以两臂度之,故仞亦或言八尺,\n⒈找，探求～找。～觅。～访。～求。～根究底。\n⒉随即，不久～即。\n⒊〈古〉长度单位。八尺为～，十六尺为常◇来用\"寻常\"〈表〉平常、普通的意思。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寻"},{"id":"glyph-seal-5bfc","script":"seal","character":"导","reading":"dǎo","description":"教导","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-导"},{"id":"glyph-seal-5bff","script":"seal","character":"寿","reading":"shòu","description":"斯役之价值,直可惊天地,泣鬼神,与武\n⒈生命的年限，又指岁数大～命。高～。～比南山。\n⒉生日～辰。祝～。\n⒊装殓死人的～衣。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寿"},{"id":"glyph-seal-5c01","script":"seal","character":"封","reading":"fēng","description":"fēng：(1)密闭，使跟外面隔绝～闭。密～。～口。～存。～条。～贮。～面。～底。～锁。～顶。冰～雪飘。～山育林。\n(2)用来装信、钱等物的纸套信～。赏～。\n(3)帝王把土地或爵位给予亲属或臣僚～侯。～君（领有封地的贵族）。～邑。～拜（拜官授爵）。～典。～建。\n(4)疆界～疆。～域。～界。\n(5)限制故步自～。\n(6)帝王筑坛祭天～禅（祭天为封”，祭地为禅”）。\n(7)量词，用于装封套的东西一～信。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-封"},{"id":"glyph-seal-5c04","script":"seal","character":"射","reading":"shè；yè；yì","description":"shè：(1)放箭～箭◇羿～日。\n(2)用推力或弹力送出子弹等～击。扫～。发～。～程。～手。\n(3)气体或液体等受到压力迅速流出喷～。注～。\n(4)放出光、热、电波等～电。辐～。～线。照～。反～。\n(5)有所指暗～。影～。\nyè：〔～干〕古书上的一种草，根可入药。\n〔仆～〕中国秦至宋代的官名，宋代以后废。\nyì：〔无～〕a.中国古代音乐十二律之一；b.中国春秋时景王所铸钟名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-射"},{"id":"glyph-seal-5c06","script":"seal","character":"将","reading":"jiāng","description":"扶持,扶助\n奉行,秉承\n⒈快要～要。她～去北京。\n⒉介词。把～祖国建设得更加美好。\n⒊拿，用，随顺～功补过。～计就计。\n⒋调养，保养～养。～息。\n⒌扶，持，带领出入相扶～。挈妇～雏。\n①对高级军官的称呼。\n⒍用语言刺激你把他～急了。\n⒎〈方〉兽类生子～驹子。～小猪儿。\n⒏副词。又，且～信～疑。\n⒐连词⊥，与，同暂伴月～影。\n⒑助词。用于动词\"出来\"、\"起来\"、\"进去\"等的中间跳～出来～起来。打～进去。迎～上去。\n⒈带兵的人，高级武官～领。猛～。虎～。\n⒉敢想敢干的人闯～。\n⒊军衔名。在校级之上少～。上～。\n⒋统率，指挥～兵打仗。\n将qiāng 1.愿;请。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-将"},{"id":"glyph-seal-5c09","script":"seal","character":"尉","reading":"wèi；yù","description":"wèi：(1)古代官名，一般是武官县～。都～。卫～。太～。\n(2)军衔的一级，在校以下～官。少～。上～。\n(3)姓。\n〔～氏〕地名，在中国河南省。\nyù：〔～迟〕复姓。\n〔～犁〕地名，在中国新疆维吾尔自治区。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尉"},{"id":"glyph-seal-5c0a","script":"seal","character":"尊","reading":"zūn","description":"zūn：(1)地位或辈分高～长（zhǎng）。～卑。～贵。～严。\n(2)敬重～敬。自～。～重。\n(3)敬辞，称与对方有关的人或事物～府。令～。～姓。～驾。\n(4)量词一～佛像。\n(5)古同撙”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尊"},{"id":"glyph-seal-5c0f","script":"seal","character":"小","reading":"xiǎo","description":"xiǎo：(1)指面积、体积、容量、数量、强度、力量不及一般或不及所比较的对象，与大”相对～雨。矮～。短～精悍。\n(2)范围窄，程度浅，性质不重要～事。～节。～题大作。～打～闹。\n(3)时间短～坐。～住。\n(4)年幼小，排行最末～孩。\n(5)谦辞～弟。～可。～人（a.谦称自己，指地位低；b.指人格卑鄙的人；c.指子女；d.小孩儿）。\n(6)妾～房。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-小"},{"id":"glyph-seal-5c11","script":"seal","character":"少","reading":"shǎo；shào","description":"shǎo：(1)数量小的，与多”相对多～。～量。～许。\n(2)缺，不够缺～。减～。\n(3)不经常～有。～见。\n(4)短时间～等。～候。～顷。\n(5)丢，遗失屋里～了东西。\n(6)轻视且夫我尝闻～仲尼之闻而轻伯夷之义者，如吾弗信，今我睹子之难穷也”。\n长；老；多；\nshào：(1)年纪轻或年轻人～年。～女。～壮（年轻力壮）。\n(2)古代辅佐长官的副职～傅。～保。\n(3)次级的～校。～将（jiàng）。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-少"},{"id":"glyph-seal-5c14","script":"seal","character":"尔","reading":"ěr","description":"后引作薾。华盛的样子\n近。通迩”\n浅近\n⑥词尾。相当于'地'、'然'卓～、率～。\n【尔曹】你们这些人。\n【尔虞我诈】互相猜疑，互相欺骗。又作尔诈我虞。\n【尔诈我虞】见【尔虞我诈】。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尔"},{"id":"glyph-seal-5c1a","script":"seal","character":"尚","reading":"shàng","description":"shàng：(1)还（hái），仍然～小。～未。～不可知。\n(2)尊崇，注重～武。～贤（a.崇尚贤人；b.《墨子》篇名，内容阐述墨子的一种政治主张）。\n(3)社会上共同遵从的风俗、习惯等风～。时～。\n(4)矜夸，自负自～其功。\n(5)古，久远故乐之所由来者～矣，非独为一世之所造也”。\n(6)庶几，差不多～飨（希望死者来享用祭品之意）。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尚"},{"id":"glyph-seal-5c1d","script":"seal","character":"尝","reading":"cháng","description":"尝试\n经历\n①吃一点试试；辨别滋味～鲜。\n②曾经未～、何～。\n【尝新】吃应时的新鲜蔬菜、水果等。\n⒉试，试一试～试。\n⒊曾经何～？","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尝"},{"id":"glyph-seal-5c24","script":"seal","character":"尤","reading":"yóu","description":"yóu：(1)特异的，突出的～为（wéi）。～异。无耻之～。\n(2)更加，格外～其。\n(3)过失效～（学着别人做坏事）。\n(4)怨恨，归咎怨天～人。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尤"},{"id":"glyph-seal-5c25","script":"seal","character":"尥","reading":"liào","description":"liào：骡马等跳起来用后腿向后踢～蹶子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尥"},{"id":"glyph-seal-5c27","script":"seal","character":"尧","reading":"yáo","description":"中国古代的皇帝陶唐氏之号。生于伊,嗣后耆,故称伊耆氏;初封陶,后徙唐,又称伊唐氏”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尧"},{"id":"glyph-seal-5c2c","script":"seal","character":"尬","reading":"gà","description":"gà：〔尴～〕见尴”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尬"},{"id":"glyph-seal-5c31","script":"seal","character":"就","reading":"jiù","description":"jiù：(1)凑近，靠近避难～易。～着灯看书。\n(2)到，从事，开始进入～位。～业。～寝。～任。～绪。～医。高～。\n(3)依照现有情况或趁着当前的便利，顺便～近。～便。～事论事。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-就"},{"id":"glyph-seal-5c38","script":"seal","character":"尸","reading":"shī","description":"shī：(1)死人的身体～体。～骸。僵～。借～还魂。\n(2)古代祭祀时，代表死者受祭的人。\n〔～位〕空占着职位而不做事，如～～素餐，～～误国”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尸"},{"id":"glyph-seal-5c39","script":"seal","character":"尹","reading":"yǐn","description":"yǐn：(1)治理以～天下。\n(2)官名令～。府～。京兆～。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尹"},{"id":"glyph-seal-5c3a","script":"seal","character":"尺","reading":"chǐ；chě","description":"chǐ：(1)中国市制长度单位（亦称市尺”。一尺等于十寸。西汉时一尺等于0.231米，今三尺等于一米）～素（a.一尺长的白绢，借指小画幅；b.书信）。～短寸长。～牍。\n(2)量长度的器具竹～。\n(3)像尺的东西铁～。仿～。戒～。\n(4)形容微少或短小～布。咫～天涯。\nchě：中国古代乐谱的记音符号，相当于简谱的2”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尺"},{"id":"glyph-seal-5c3b","script":"seal","character":"尻","reading":"kāo","description":"kāo：(1)屁股，脊骨的末端～骨（坐骨）。\n(2)家畜外形部位名称（以髋骨、荐骨和部分尾椎骨为基础，前连腰，下接股。是推动后股运步的重要部位）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尻"},{"id":"glyph-seal-5c3c","script":"seal","character":"尼","reading":"ní","description":"ní：(1)梵语比丘尼”的简称，佛教中出家修行的女子～姑。～庵。削发为～。\n(2)古同昵”，相近，亲近。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尼"},{"id":"glyph-seal-5c3d","script":"seal","character":"尽","reading":"jìn","description":"尽量,尽可能\n意思同最”,用在方位词的前面\n老是;总\n尽 〈动〉\n表示以某个范围为界限,不得超过\n让先\n任凭,纵使\n惟有落红不禁,尽教飞舞出宫墙。╠\n⒈力所能及的限度～力。～量。\n⒉放在最先住房先～着分给教师。\n⒊任凭～你挑选。\n⒋极，最～前头。～下面。～先考虑。\n⒌老是，只管这几天～是晴天。\n①纵然，即使～管如此。\n②只管，不必考虑的你～管放心。\n⒈完无穷无～。取之不～。\n⒉全部用出，竭力做到～心竭力。～力而为。～职～责。～情欢唱。各～所能。\n⒊达到顶点已到～头。～善～美。\n⒋都，全部～人皆知。满城～带黄金甲。\n⒍见jǐn。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尽"},{"id":"glyph-seal-5c3e","script":"seal","character":"尾","reading":"wěi；yǐ","description":"wěi：(1)鸟兽虫鱼等身体末端突出的部分～巴。～鳍。鸟～。\n(2)末端排～。船～。～声。～骨。～灯。～数。～音。结～。扫～。虎头蛇～。\n(3)在后面跟～随。～追。\n(4)量词，指鱼三～鱼。\n(5)星名，二十八宿之一。\n头；首；\nyǐ：(1)特指马尾（wěi）巴上的毛马～罗。马～儿提豆腐╠提溜不起来。\n(2)特指蟋蟀等尾部的针状物三～儿（雌蟋蟀）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尾"},{"id":"glyph-seal-5c3f","script":"seal","character":"尿","reading":"niào；suī","description":"niào：(1)小便，肾脏的排泄液～液。～布。～肥。～素。\n(2)排泄小便～尿。\nsuī：小便（限于名词）尿（niào）～。～脬（膀胱。亦作尿泡”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尿"},{"id":"glyph-seal-5c40","script":"seal","character":"局","reading":"jú；jv","description":"jú：(1)部分～部。～麻（局部麻醉）。\n(2)机关及团体组织分工办事的单位教育～。\n(3)某些商店的名称书～。\n(4)棋盘棋～。\n(5)下棋或其他比赛进行一次下了一～棋。\n(6)着棋的形势，喻事情的形势、情况时～。大～。～面。～势。\n(7)弯曲。\n(8)骗人的圈套骗～。\n(9)畏缩不安，狭隘，不舒展～促。～限。\n(10)人的器量～量（liàng）。器～。～度（dù）。\n(11)某些聚会饭～。饮～。赌～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-局"},{"id":"glyph-seal-5c42","script":"seal","character":"层","reading":"céng","description":"构成整个事物的一个层次\n重叠\n层台累榭。\n①量词。用于重叠、可分出层次的事物千～饼、三～楼。\n②重叠；重复～峦叠嶂。\n【层出不穷】接连不断地出现，没有尽头。层重迭；重复。穷尽；完。\n【层递】〈语〉修辞学上辞格之一。用结构相似的语句表达层层递进的事理。如'火车风驰电掣地猛冲过来……五十米，马不动。四十米，马不动。三十米，马还是不动！'\n【层析】色层分析的简称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-层"},{"id":"glyph-seal-5c45","script":"seal","character":"居","reading":"jū；jv","description":"jū：(1)住～住。～民。同～。隐～。～处（chǔ）（a.住所；b.指生活处境）。～处（chù）（住所）。\n(2)居住的地方新～。故～。迁～。蜗～（喻窄小的住所）。\n(3)当，占，处于～首。～中。～高临下。二者必～其一。\n(4)安着，怀着～心（怀着某种念头，有贬义）。\n(5)积蓄，储存奇货可～（a.指商人把珍稀的货物储存起来，等待时机高价出售；b.喻挟持某种技艺或某种事物以谋求功名利禄）。\n(6)停留～守。\n(7)平时平～。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-居"},{"id":"glyph-seal-5c48","script":"seal","character":"屈","reading":"qū","description":"qū：(1)使弯曲，与伸”相对～曲（qū）。～折。～膝。～伸（弯曲和伸直，引申为失意和得意）。首～一指。卑躬～膝。\n(2)低头，降服～服。～从。威武不～。\n(3)冤枉，叫人不痛快冤～。委～。～辱。～才。～就（受委屈而担任某种职务，常用于请人任职的客套话）。～驾。～己待人。\n(4)理亏～心（亏心，昧心）。理～词穷。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屈"},{"id":"glyph-seal-5c4a","script":"seal","character":"届","reading":"jiè","description":"jiè：(1)到～时。～期。\n(2)量词，略同于次”，用于定期的会议或毕业的班级等上～。应～（指本期的，用于毕业生）。第一～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-届"},{"id":"glyph-seal-5c4b","script":"seal","character":"屋","reading":"wū","description":"wū：(1)房，房间～子。～宇。房～。\n(2)家吴中过客莫思家，江南画船如～里。”\n(3)车盖，覆盖物黄～（古代帝王所乘车上以黄缯为里的车盖，亦指帝王车）。～社（王朝倾覆的代称）。\n(4)古代井田的区划，一屋合三百亩。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屋"},{"id":"glyph-seal-5c4f","script":"seal","character":"屏","reading":"píng；bǐng","description":"píng：(1)遮挡～风。～障。～蔽。～藩（屏风”和藩篱”，喻卫国的重臣）。～翰（喻卫国的重臣）。\n(2)字画的条幅，通常以四幅或八幅为一组画～。四扇～。\nbǐng：(1)除去，排除～除。～弃。～斥。～退。\n(2)抑止（呼吸）～气。～息。～声。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屏"},{"id":"glyph-seal-5c50","script":"seal","character":"屐","reading":"jī","description":"jī：木头鞋，泛指鞋木～。～履。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屐"},{"id":"glyph-seal-5c51","script":"seal","character":"屑","reading":"xiè","description":"xiè：(1)碎末～子。纸～。\n(2)琐碎～～。琐～（细微小的事情）。\n(3)认为值得（做）不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屑"},{"id":"glyph-seal-5c55","script":"seal","character":"展","reading":"zhǎn","description":"zhǎn：(1)张开，舒张开～开。～示。～玩。～现。～宽。～望。发～。愁眉不～。\n(2)延缓，放宽期限～延。～期。～缓。\n(3)察看，省（xǐng）视～墓。\n(4)陈列～品。～销。～播。～评。\n(5)施行，发挥（能力）～拜。开～。施～。一～宏图。\n(6)古同辗”，辗转。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-展"},{"id":"glyph-seal-5c5e","script":"seal","character":"属","reading":"shǔ","description":"种类。亦特指牲类\n亲属\n侪辈。指同一类人\n若属皆且为所\n⒈类，同一类型的种～。金～。非金～。\n⒉同一家族的亲～。家～。\n⒊有管辖关系的直～。隶～。归～。附～。\n⒋是事～可行。经查～实。\n⒌归类～于医学。\n⒍为谁所有那支笔～你的。\n⒈连接，跟着前后相～。\n⒉编写，连缀～文。～辞。\n⒊专注～意。～望。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-属"},{"id":"glyph-seal-5c60","script":"seal","character":"屠","reading":"tú","description":"tú：(1)宰杀牲畜，引申为大量残杀～宰。～刀。～户。～夫。～杀。～戮。～城。～龙之技（喻高超而不实用的技艺）。\n(2)姓。\n〔～苏〕a.古书上说的一种草；b.草庵；c.古代一种酒名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屠"},{"id":"glyph-seal-5c61","script":"seal","character":"屡","reading":"lǚ","description":"屡（屢）lǚ多次～次。～见不鲜。～战～胜。～禁不止。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屡"},{"id":"glyph-seal-5c65","script":"seal","character":"履","reading":"lǚ；lv","description":"lǚ：(1)鞋西装革～。削足适～。\n(2)践踩，走过～历（a.个人的经历；b.记载履历的文件）。～任。～险如夷（走在险峻的地方，像走在平坦的路上，喻身处险境而不畏惧，又喻安全地度过险境）。如～薄冰（身临其境）。\n(3)步伐步～维艰。\n(4)执行，实行～行。～约。\n(5)指领土赐我先君～”。\n〔～带〕在拖拉机、坦克车等的车轮上围绕的钢质链带。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-履"},{"id":"glyph-seal-5c66","script":"seal","character":"屦","reading":"jù；jv","description":"⒈〈古〉用麻、葛等制成的一种鞋麻～。葛～。\n⒉〈古〉践踏。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屦"},{"id":"glyph-seal-5c6f","script":"seal","character":"屯","reading":"tún；zhūn","description":"tún：(1)聚集，储存～粮。～积。～聚。\n(2)驻军防守～兵。～垦。～田（驻军开垦田地）。\n(3)村庄皇姑～。～子（村庄）。\nzhūn：困难～蹇（不顺利，艰难困苦）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屯"},{"id":"glyph-seal-5c71","script":"seal","character":"山","reading":"shān","description":"地面上高耸的地形，也用来指山峦。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-seal-5c7a","script":"seal","character":"屺","reading":"qǐ","description":"qǐ：没有草木的山。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屺"},{"id":"glyph-seal-5c7f","script":"seal","character":"屿","reading":"yǔ","description":"平地小山","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屿"},{"id":"glyph-seal-5c81","script":"seal","character":"岁","reading":"suì","description":"年的别称\n⒈年，时间，光阴～首。～末。～月如流。\n⒉计算年龄的单位～数。六～入学。\n⒊庄稼的收成～景。善～。丰～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岁"},{"id":"glyph-seal-5c82","script":"seal","character":"岂","reading":"qǐ","description":"同恺”。安乐\n岂”假借作虚词,用在句中或句首,表示反问。\n相当于难道”,怎么”\n相当\n⒉〈古〉通\"恺\"、\"凯\"。柔和，快乐。\n岂kǎi 1.和乐。参见\"岂乐\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岂"},{"id":"glyph-seal-5c8c","script":"seal","character":"岌","reading":"jí","description":"jí：〔～～〕山耸起的样子；亦喻危险，如～～可危”，～～不可终日”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岌"},{"id":"glyph-seal-5c90","script":"seal","character":"岐","reading":"qí","description":"qí：同歧”。\n〔～山〕山名，在中国陕西省。\n〔～黄之术〕指中医的医术。岐”，岐伯；黄”，黄帝，相传他们都是中华民族医家之祖。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岐"},{"id":"glyph-seal-5c91","script":"seal","character":"岑","reading":"cén","description":"cén：(1)小而高的山。\n(2)崖岸。\n(3)姓。\n〔～寂〕寂静，寂寞。\n〔～～〕形容烦闷。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岑"},{"id":"glyph-seal-5c9a","script":"seal","character":"岚","reading":"lán","description":"岚lán山里的雾气晓～。夕～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岚"},{"id":"glyph-seal-5c9b","script":"seal","character":"岛","reading":"dǎo","description":"字省作岛”\n岛 dǎo海洋里被水环绕、面积比大陆小的陆地。也指江河湖里被水环绕的陆地。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岛"},{"id":"glyph-seal-5ca9","script":"seal","character":"岩","reading":"yán","description":"yán：(1)高峻的山崖～壁。～壑。\n(2)构成地壳的石头～石。～洞。～浆。～层。熔～。\n(3)险要，险峻～险。～邑。\n(4)山洞中空成～。～居穴处。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岩"},{"id":"glyph-seal-5cab","script":"seal","character":"岫","reading":"xiù","description":"xiù：(1)山洞云无心以出～，鸟倦飞而知还”。～居。岩～。\n(2)山远～。巫～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岫"},{"id":"glyph-seal-5cad","script":"seal","character":"岭","reading":"lǐng；líng","description":"líng：〔～嵤〕山深貌。亦作岭巆”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岭"},{"id":"glyph-seal-5cb1","script":"seal","character":"岱","reading":"dài","description":"dài：中国泰山的别称。亦称岱宗”、岱岳”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岱"},{"id":"glyph-seal-5cb3","script":"seal","character":"岳","reading":"yuè","description":"yuè：(1)高大的山五～（中国五大名山，即东岳泰山，西岳华山，南岳衡山，北岳恒山，中岳嵩山）。\n(2)称妻的父母或妻的叔伯～丈。～父。～母。叔～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岳"},{"id":"glyph-seal-5cb8","script":"seal","character":"岸","reading":"àn","description":"àn：(1)水边的陆地河～。上～。两～。\n(2)高大伟～（魁伟，高直）。魁～。\n(3)高傲～忽（傲慢）。傲～。\n(4)头饰高戴，前额外露～帻（把头巾掀起露出前额，表示态度洒脱，不拘束）。\n(5)古同犴”，乡间牢狱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岸"},{"id":"glyph-seal-5cc4","script":"seal","character":"峄","reading":"yì","description":"山名,又名邹山\n峄yì 峄县，在山东省,现划归枣庄市.\n峄yì山名，峄山又名邹山。在山东邹县东南。\n【峄县】旧县名。在山东省南部。1960年撤销，改设枣庄市。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-峄"},{"id":"glyph-seal-5ccb","script":"seal","character":"峋","reading":"xún","description":"xún：〔嶙（lín）～〕见嶙”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-峋"},{"id":"glyph-seal-5ce3","script":"seal","character":"峣","reading":"yáo","description":"峣（巃）yáo高，山高～ ～峰峦。岧～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-峣"},{"id":"glyph-seal-5ce4","script":"seal","character":"峤","reading":"qiáo；jiao","description":"山道\n特指五岭\n本指高而尖的山。泛指高山或山岭\n同乔”。高\n⒈山道。\n⒉见qiáo。\n⒈尖而高的山千～万峰。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-峤"},{"id":"glyph-seal-5ce6","script":"seal","character":"峦","reading":"luán","description":"泛指山\n⒈小而尖的山孤～。丘～崩摧。\n⒉山脊，山梁，泛指山，多指连着的山冈～。峰～起伏。重～迭嶂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-峦"},{"id":"glyph-seal-5ce8","script":"seal","character":"峨","reading":"é","description":"é：高～～。～冠博带。巍～。嵯～。\n〔～嵋〕山名，在中国四川省。亦作蛾眉”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-峨"},{"id":"glyph-seal-5ced","script":"seal","character":"峭","reading":"qiào","description":"qiào：(1)山又高又陡陡～。～壁。峻～。～立。～丽（a.陡峭而多姿；b.文辞遒劲华美）。～拔。\n(2)形容严峻～寒。～急。～劲。～厉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-峭"},{"id":"glyph-seal-5cf0","script":"seal","character":"峰","reading":"fēng","description":"fēng：(1)高而尖的山头山～。～巅。～峦。高～。险～。\n(2)形状像山峰的东西驼～。浪～。\n(3)最高处登～造极。～年（自然界中某种活动达到高峰的年度）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-峰"},{"id":"glyph-seal-5cfb","script":"seal","character":"峻","reading":"jùn","description":"jùn：(1)山高而陡高～。险～。～峭。～拔。\n(2)高大～德。～节。\n(3)严厉苛刻～刻。～厉。严～。严刑～法。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-峻"},{"id":"glyph-seal-5d07","script":"seal","character":"崇","reading":"chóng","description":"chóng：(1)高～山峻岭。～高。～论闳议（指高出一般人的讨论。亦作崇论宏议”）。\n(2)尊重，推重～敬。～拜。～尚。推～。尊～。\n(3)古同终”，终了。\n(4)充，充满～酒于觞。\n(5)增长今将～诸侯之奸”。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-崇"},{"id":"glyph-seal-5d0e","script":"seal","character":"崎","reading":"qí","description":"qí：〔～岖〕形容山路不平。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-崎"},{"id":"glyph-seal-5d14","script":"seal","character":"崔","reading":"cuī","description":"cuī：姓。\n〔～巍〕山、建筑物高大伟岸。\n〔～嵬〕a.有石头的土山；b.高大。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-崔"},{"id":"glyph-seal-5d16","script":"seal","character":"崖","reading":"yá","description":"yá：(1)高地的边，陡立的山边山～。悬～。～谷。～壑。～壁。～葬（悬棺葬）。～岸。悬～勒马。\n(2)边际～略（大略，梗概）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-崖"},{"id":"glyph-seal-5d1b","script":"seal","character":"崛","reading":"jué","description":"jué：高起，突起～起（a.山峰突起，如泰山平地～～”；b.喻兴起，如义军～～于村野”）。～立（耸立）。～崎。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-崛"},{"id":"glyph-seal-5d29","script":"seal","character":"崩","reading":"bēng","description":"bēng：(1)倒塌～塌。～坍。～毁。～解（jiě）。～溃。～决。～颓。分～离析。\n(2)破裂～裂。把气球吹～了。\n(3)崩裂的东西击中放爆竹～了手。\n(4)败坏礼坏乐（yuè）～。\n(5)称枪毙拉出去～了。\n(6)君主时代称帝王死驾～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-崩"},{"id":"glyph-seal-5d47","script":"seal","character":"嵇","reading":"jī；jí","description":"jí：姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嵇"},{"id":"glyph-seal-5d4c","script":"seal","character":"嵌","reading":"qiàn；kàn","description":"qiàn：把东西填镶在空隙里～入。镶～。\nkàn：〔赤～〕地名，在中国台湾省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嵌"},{"id":"glyph-seal-5d4e","script":"seal","character":"嵎","reading":"yú","description":"⒈山弯曲处。\n⒉同\"隅\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嵎"},{"id":"glyph-seal-5d58","script":"seal","character":"嵘","reading":"róng","description":"见“峥嵘”，形容山势高峻，也形容才气、品格等不平凡。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-5d69","script":"seal","character":"嵩","reading":"sōng","description":"sōng：高～峦（高耸的峰峦）。～呼（亦称山呼”）。\n〔～山〕山名，在中国河南省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嵩"},{"id":"glyph-seal-5d6c","script":"seal","character":"嵬","reading":"wéi","description":"wéi：高大。\n〔崔～〕见崔”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嵬"},{"id":"glyph-seal-5d6f","script":"seal","character":"嵯","reading":"cuó","description":"cuó：〔～峨〕山势高峻的样子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嵯"},{"id":"glyph-seal-5d99","script":"seal","character":"嶙","reading":"lín","description":"lín：〔～峋〕a.山石一层层的重叠不平，如～～的巨石”；b.形容人瘦削，如瘦骨～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嶙"},{"id":"glyph-seal-5db7","script":"seal","character":"嶷","reading":"yí；ni","description":"yí：〔九～〕山名，在湖南省。相传是舜安葬的地方；又指九嶷山之神，如～～缤兮并迎。”。亦作九疑”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嶷"},{"id":"glyph-seal-5dcd","script":"seal","character":"巍","reading":"wēi","description":"wēi：高大～峨。～焕（高大壮观）。～然。～～。崔～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巍"}];
